import type { IPlugin } from '@shell/core/types';
import { ALLOWED_GETTER } from './lib/gate';

export const NAME = 'multisite-cluster-provisioner';

// Das Produkt wird SYNCHRON registriert — und über `ifGetter` gefiltert.
//
// Warum synchron: Der Router ruft direkt nach dem Laden der Extension `setProduct()`
// auf. Ist bei gesetztem `meta.product` das Produkt noch nicht in `state.products`,
// erzeugt die Shell `productNotFound` (shell/utils/product.ts). Eine asynchrone
// Registrierung kommt für den ersten Direktaufruf beider Plugin-URLs immer zu spät —
// Berechtigte bekämen einen Fail-Whale. `isProductRegistered` liest `state.products`,
// nicht `activeProducts`; die Route findet das Produkt also immer.
//
// Warum trotzdem nichts sichtbar wird: `activeProducts` filtert jedes Produkt mit
// `ifGetter` heraus, solange `rootGetters[ifGetter]` falsy ist (shell/store/type-map.js).
// Ist der Store `multisiteAccess` noch nicht registriert, ist der Getter `undefined` —
// also ebenfalls falsy. Der Menüpunkt ist damit fail-closed und rein reaktiv an
// `multisiteAccess/allowed` gebunden; es gibt kein nachträgliches Registrieren und
// kein Aufräumen per removeProduct mehr.
export function init($plugin: IPlugin, store: any): void {
  const { product } = $plugin.DSL(store, NAME);

  product({
    inStore:             'management',
    icon:                'globe',
    label:               'Multi-Site Cluster Provisioner',
    removable:           false,
    showClusterSwitcher: false,
    category:            'global',
    ifGetter:            ALLOWED_GETTER,
    to:                  { name: NAME },
  } as any);
}
