<script>
import {
  ALLOWED_GETTER, accessEpoch, fencedStore, isEpochCurrent, revalidateAccess,
} from '../lib/gate';
import {
  CEPH_STORAGE_ENCRYPTION_MODES, CEPH_STORAGE_ENCRYPTION_MODE_DEFAULT,
  CEPH_STORAGE_GIB_DEFAULT, CEPH_STORAGE_GIB_MAX, CEPH_STORAGE_GIB_MIN, CEPH_STORAGE_GIB_STEP,
  KUBERNETES_VERSIONS, SIZE_CLASSES, cephStorageFieldError, clusterNameFieldError, createRequest,
  describeRequestError, isValidNodeSizes, listCustomers, listRequests, nodeSizeFieldErrors,
  paginateRequests, sortRequestsNewestFirst, zoneClusterNames,
} from '../lib/requests';

const PHASES = [
  'Pending',
  'Validating',
  'FabricProvisioning',
  'FabricVerified',
  'ClusterProvisioning',
  'ClusterActive',
  'FleetPublishing',
  'Ready',
];
const TERMINAL_PHASES = new Set(['Ready', 'Blocked', 'Failed']);

export default {
  name:   'ProvisionWizard',
  layout: 'plain',

  data() {
    return {
      customers: [],
      requests:  [],
      form: {
        customerUuid:     '',
        clusterName:      '',
        kubernetesVersion: KUBERNETES_VERSIONS[0],
        nodeSizes:         {
          controlPlane: { ...SIZE_CLASSES.M.controlPlane },
          worker: { ...SIZE_CLASSES.M.worker },
          controlPlaneIsWorker: SIZE_CLASSES.M.controlPlaneIsWorker,
        },
        networkMode:      'new',
        zoneLabel:        '',
        fabricVrfId:      '',
        cephStorageEnabled: false,
        cephStorageGiB:     CEPH_STORAGE_GIB_DEFAULT,
        cephStorageEncryptionMode: CEPH_STORAGE_ENCRYPTION_MODE_DEFAULT,
        veleroBackup:       false,
      },
      encryptionModes:    CEPH_STORAGE_ENCRYPTION_MODES,
      phases:             PHASES,
      storageLimits:      {
        min: CEPH_STORAGE_GIB_MIN, max: CEPH_STORAGE_GIB_MAX, step: CEPH_STORAGE_GIB_STEP,
      },
      kubernetesVersions: KUBERNETES_VERSIONS,
      presets:            Object.keys(SIZE_CLASSES),
      currentRequestId:   '',
      requestPage:        1,
      loading:            true,
      submitting:         false,
      error:              '',
      submitError:        '',
      pollTimer:          null,
    };
  },

  computed: {
    allowed() {
      return this.$store.getters[ALLOWED_GETTER] === true;
    },
    selectedCustomer() {
      return this.customers.find((entry) => entry?.spec?.customerUuid === this.form.customerUuid);
    },
    customerZones() {
      const zones = this.selectedCustomer?.spec?.routingZones;

      return Array.isArray(zones) ? zones : [];
    },
    selectedZone() {
      return this.customerZones.find((zone) => zone?.fabricVrfId === this.form.fabricVrfId) || null;
    },
    currentRequest() {
      return this.requests.find((entry) => entry?.spec?.requestId === this.currentRequestId) || null;
    },
    sortedRequests() {
      return sortRequestsNewestFirst(this.requests);
    },
    requestPagination() {
      return paginateRequests(this.sortedRequests, this.requestPage);
    },
    clusterNameError() {
      return clusterNameFieldError(this.form.clusterName);
    },
    currentPhase() {
      return this.currentRequest?.status?.phase || '';
    },
    currentMessage() {
      return this.currentRequest?.status?.message || '';
    },
    workerCount() {
      return this.form.nodeSizes.worker.countBerlin1 + this.form.nodeSizes.worker.countBerlin2;
    },
    sizeErrors() {
      return nodeSizeFieldErrors(this.form.nodeSizes);
    },
    storageError() {
      return this.form.cephStorageEnabled ? cephStorageFieldError(this.form.cephStorageGiB) : null;
    },
    encryptionLabel() {
      const mode = this.encryptionModes.find((m) => m.value === this.form.cephStorageEncryptionMode);

      return mode ? mode.label : this.form.cephStorageEncryptionMode;
    },
    resourceTotals() {
      const { controlPlane: cp, worker: wk } = this.form.nodeSizes;
      const site = (controlPlanes, workers) => ({
        nodes:  controlPlanes + workers,
        cpu:    controlPlanes * cp.cpu + workers * wk.cpu,
        memory: controlPlanes * cp.memoryGiB + workers * wk.memoryGiB,
        disk:   controlPlanes * cp.diskGiB + workers * wk.diskGiB,
      });
      const berlin1 = site(cp.countBerlin1, this.form.nodeSizes.worker.countBerlin1);
      const berlin2 = site(cp.countBerlin2, this.form.nodeSizes.worker.countBerlin2);
      // Hannover-Witness ist fix (reiner etcd-Voter): 4 CPU / 8 GiB / 40 GiB.
      const witness = {
        nodes: 1, cpu: 4, memory: 8, disk: 40,
      };
      const total = {
        nodes:  berlin1.nodes + berlin2.nodes + witness.nodes,
        cpu:    berlin1.cpu + berlin2.cpu + witness.cpu,
        memory: berlin1.memory + berlin2.memory + witness.memory,
        disk:   berlin1.disk + berlin2.disk + witness.disk,
      };

      return {
        berlin1, berlin2, witness, total,
      };
    },
    canSubmit() {
      return this.allowed && !this.loading && !this.submitting &&
        this.form.customerUuid && this.form.clusterName && !this.clusterNameError &&
        this.form.kubernetesVersion && isValidNodeSizes(this.form.nodeSizes) && !this.storageError &&
        (this.form.networkMode !== 'existing' || !!this.selectedZone);
    },
  },

  watch: {
    'form.customerUuid'() {
      // Zonen gehören zum Kunden: Kundenwechsel setzt die Zielwahl zurück.
      this.form.networkMode = 'new';
      this.form.fabricVrfId = '';
    },
    'form.networkMode'(mode) {
      if (mode === 'existing') {
        this.form.zoneLabel = '';
      } else {
        this.form.fabricVrfId = '';
      }
    },
  },

  async mounted() {
    if (!await revalidateAccess(this.$store)) {
      this.loading = false;

      return;
    }

    await this.refresh();
  },

  beforeDestroy() {
    this.stopPolling();
  },

  methods: {
    applyPreset(preset) {
      const nodeSizes = SIZE_CLASSES[preset];

      this.form.nodeSizes = {
        controlPlane: { ...nodeSizes.controlPlane },
        worker: { ...nodeSizes.worker },
        controlPlaneIsWorker: nodeSizes.controlPlaneIsWorker,
      };
    },
    stillCurrent(epoch) {
      return isEpochCurrent(this.$store, epoch);
    },
    requestStore(epoch) {
      return fencedStore(this.$store, epoch, (candidate) => this.stillCurrent(candidate));
    },
    async refresh() {
      const epoch = accessEpoch(this.$store);

      if (!this.stillCurrent(epoch)) {
        return;
      }

      try {
        const store = this.requestStore(epoch);
        const [customers, requests] = await Promise.all([
          listCustomers(store),
          listRequests(store),
        ]);

        if (!this.stillCurrent(epoch)) {
          return;
        }

        this.customers = customers;
        this.requests = requests;
        if (!this.form.customerUuid && customers.length === 1) {
          this.form.customerUuid = customers[0].spec.customerUuid;
        }
        this.error = '';
      } catch (e) {
        if (this.stillCurrent(epoch)) {
          this.error = `Katalog oder Status konnten nicht geladen werden: ${ e?.message || e }`;
        }
      } finally {
        if (this.stillCurrent(epoch)) {
          this.loading = false;
        }
      }
    },
    async submit() {
      this.submitError = '';
      this.submitting = true;

      try {
        if (!await revalidateAccess(this.$store)) {
          return;
        }

        const epoch = accessEpoch(this.$store);
        const created = await createRequest(this.requestStore(epoch), {
          ...this.form,
          // Die MSP-ID ist die Slot-Identität der gewählten Zone aus dem
          // Katalog; der Server prüft sie gegen den Ziel-VRF.
          mspId: this.selectedZone?.mspId,
        });

        if (!this.stillCurrent(epoch)) {
          return;
        }

        this.currentRequestId = created?.spec?.requestId || created?.data?.spec?.requestId || '';
        // Die neue Anforderung ist die neueste und steht damit auf Seite 1.
        this.requestPage = 1;
        await this.refresh();
        this.startPolling();
      } catch (e) {
        // Sichtbar direkt am Absende-Button — auch bei einer serverseitigen Ablehnung.
        this.submitError = `Die Anforderung wurde nicht angelegt: ${ describeRequestError(e) }`;
      } finally {
        this.submitting = false;
      }
    },
    startPolling() {
      this.stopPolling();
      if (!this.currentRequestId || TERMINAL_PHASES.has(this.currentPhase)) {
        return;
      }
      this.pollTimer = window.setInterval(async () => {
        await this.refresh();
        if (TERMINAL_PHASES.has(this.currentPhase)) {
          this.stopPolling();
        }
      }, 5000);
    },
    stopPolling() {
      if (this.pollTimer) {
        window.clearInterval(this.pollTimer);
        this.pollTimer = null;
      }
    },
    isComplete(phase) {
      const current = PHASES.indexOf(this.currentPhase);

      return current >= PHASES.indexOf(phase);
    },
    customerLabel(customer) {
      const spec = customer?.spec || {};

      return `${ spec.displayName || spec.customerUuid } · Tenant ${ spec.tenantId }`;
    },
    zoneClusters(zone) {
      // Katalogliste, sonst Ableitung aus den Anforderungen dieser Zone; sonst neutral.
      const clusters = zoneClusterNames(zone, this.requests);

      return clusters.length ? clusters.join(', ') : 'keine Cluster gemeldet';
    },
    zoneDisplay(zone) {
      const prefix = zone.label ? `${ zone.label } · ` : '';

      return `${ prefix }${ zone.name } · VLAN ${ zone.rzVlan } · ${ this.zoneClusters(zone) }`;
    },
    selectRequest(request) {
      const requestId = request?.spec?.requestId || '';

      // Erneuter Klick klappt das Inline-Detail wieder zu.
      if (requestId && requestId === this.currentRequestId) {
        this.currentRequestId = '';
        this.stopPolling();

        return;
      }

      this.currentRequestId = requestId;
      this.startPolling();
    },
    isSelected(request) {
      return !!this.currentRequestId && this.currentRequestId === request?.spec?.requestId;
    },
    formatCreated(request) {
      const stamp = Date.parse(request?.metadata?.creationTimestamp || '');

      return Number.isFinite(stamp) ? new Date(stamp).toLocaleString('de-DE') : '';
    },
  },
};
</script>

<template>
  <main class="multisite-request">
    <header class="hero">
      <div>
        <p class="eyebrow">focusnet Multisite Kubernetes</p>
        <h1>Multisite-Cluster anfordern</h1>
        <p class="lede">
          Der Broker baut Netzwerk, Witness und Cluster in einer kontrollierten Saga.
          Infrastruktur-Zugangsdaten und Adresswerte bleiben vollständig serverseitig.
        </p>
      </div>
      <span class="badge">Nur Multisite-Gruppe</span>
    </header>

    <div
      v-if="error"
      class="notice notice--error"
      role="alert"
    >
      {{ error }}
    </div>

    <section class="panel">
      <h2>Bestellung</h2>
      <div class="form-grid">
        <label>
          Kunde
          <select v-model="form.customerUuid" :disabled="loading || submitting">
            <option value="">– Kunde wählen –</option>
            <option
              v-for="customer in customers"
              :key="customer.spec.customerUuid"
              :value="customer.spec.customerUuid"
            >
              {{ customerLabel(customer) }}
            </option>
          </select>
        </label>
        <label>
          Clustername
          <input
            :class="{ 'input-error': clusterNameError }"
            v-model.trim="form.clusterName"
            maxlength="63"
            placeholder="kunde-multisite-01"
            :disabled="submitting"
          >
          <small v-if="clusterNameError" class="field-error" role="alert">
            {{ clusterNameError }}
          </small>
          <small v-else class="node-help">1–63 Zeichen: Kleinbuchstaben, Ziffern, Bindestrich; Beginn und Ende Buchstabe oder Ziffer.</small>
        </label>
        <label>
          Kubernetes-Version
          <select v-model="form.kubernetesVersion" :disabled="submitting">
            <option v-for="version in kubernetesVersions" :key="version" :value="version">
              {{ version }}
            </option>
          </select>
        </label>
      </div>
    </section>

    <section class="panel">
      <div class="node-size-heading">
        <div>
          <h2>Node-Größen</h2>
          <p class="node-help">
            Preset wählen oder die Werte passend zur Bestellung anpassen.
          </p>
        </div>
        <fieldset class="preset-row">
          <legend>Vorbelegung</legend>
          <button
            v-for="preset in presets"
            :key="preset"
            type="button"
            class="preset-button"
            :disabled="submitting"
            @click="applyPreset(preset)"
          >
            {{ preset }}
          </button>
        </fieldset>
      </div>

      <div class="node-size-groups">
        <fieldset>
          <legend>Control Plane</legend>
          <div class="node-size-grid">
            <label>
              CPU (2–32)
              <input
                :class="{ 'input-error': sizeErrors['controlPlane.cpu'] }"
                v-model.number="form.nodeSizes.controlPlane.cpu"
                type="number"
                min="2"
                max="32"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['controlPlane.cpu']" class="field-error" role="alert">
                {{ sizeErrors['controlPlane.cpu'] }}
              </small>
            </label>
            <label>
              RAM GiB (4–256)
              <input
                :class="{ 'input-error': sizeErrors['controlPlane.memoryGiB'] }"
                v-model.number="form.nodeSizes.controlPlane.memoryGiB"
                type="number"
                min="4"
                max="256"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['controlPlane.memoryGiB']" class="field-error" role="alert">
                {{ sizeErrors['controlPlane.memoryGiB'] }}
              </small>
            </label>
            <label>
              Disk GiB (40–1000)
              <input
                :class="{ 'input-error': sizeErrors['controlPlane.diskGiB'] }"
                v-model.number="form.nodeSizes.controlPlane.diskGiB"
                type="number"
                min="40"
                max="1000"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['controlPlane.diskGiB']" class="field-error" role="alert">
                {{ sizeErrors['controlPlane.diskGiB'] }}
              </small>
            </label>
            <label>
              Anzahl Berlin 1 (1–7)
              <input
                :class="{ 'input-error': sizeErrors['controlPlane.countBerlin1'] }"
                v-model.number="form.nodeSizes.controlPlane.countBerlin1"
                type="number"
                min="1"
                max="7"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['controlPlane.countBerlin1']" class="field-error" role="alert">
                {{ sizeErrors['controlPlane.countBerlin1'] }}
              </small>
            </label>
            <label>
              Anzahl Berlin 2 (1–7)
              <input
                :class="{ 'input-error': sizeErrors['controlPlane.countBerlin2'] }"
                v-model.number="form.nodeSizes.controlPlane.countBerlin2"
                type="number"
                min="1"
                max="7"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['controlPlane.countBerlin2']" class="field-error" role="alert">
                {{ sizeErrors['controlPlane.countBerlin2'] }}
              </small>
            </label>
          </div>
          <p
            v-if="sizeErrors['controlPlane.quorum']"
            class="notice notice--warning"
            role="alert"
          >
            {{ sizeErrors['controlPlane.quorum'] }}
          </p>
        </fieldset>

        <fieldset>
          <legend>Worker</legend>
          <div class="node-size-grid">
            <label>
              CPU (2–32)
              <input
                :class="{ 'input-error': sizeErrors['worker.cpu'] }"
                v-model.number="form.nodeSizes.worker.cpu"
                type="number"
                min="2"
                max="32"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['worker.cpu']" class="field-error" role="alert">
                {{ sizeErrors['worker.cpu'] }}
              </small>
            </label>
            <label>
              RAM GiB (4–256)
              <input
                :class="{ 'input-error': sizeErrors['worker.memoryGiB'] }"
                v-model.number="form.nodeSizes.worker.memoryGiB"
                type="number"
                min="4"
                max="256"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['worker.memoryGiB']" class="field-error" role="alert">
                {{ sizeErrors['worker.memoryGiB'] }}
              </small>
            </label>
            <label>
              Disk GiB (40–1000)
              <input
                :class="{ 'input-error': sizeErrors['worker.diskGiB'] }"
                v-model.number="form.nodeSizes.worker.diskGiB"
                type="number"
                min="40"
                max="1000"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['worker.diskGiB']" class="field-error" role="alert">
                {{ sizeErrors['worker.diskGiB'] }}
              </small>
            </label>
            <label>
              Anzahl Berlin 1 (0–50)
              <input
                :class="{ 'input-error': sizeErrors['worker.countBerlin1'] }"
                v-model.number="form.nodeSizes.worker.countBerlin1"
                type="number"
                min="0"
                max="50"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['worker.countBerlin1']" class="field-error" role="alert">
                {{ sizeErrors['worker.countBerlin1'] }}
              </small>
            </label>
            <label>
              Anzahl Berlin 2 (0–50)
              <input
                :class="{ 'input-error': sizeErrors['worker.countBerlin2'] }"
                v-model.number="form.nodeSizes.worker.countBerlin2"
                type="number"
                min="0"
                max="50"
                step="1"
                :disabled="submitting"
              >
              <small v-if="sizeErrors['worker.countBerlin2']" class="field-error" role="alert">
                {{ sizeErrors['worker.countBerlin2'] }}
              </small>
            </label>
          </div>
        </fieldset>
      </div>

      <label class="checkbox-row">
        <input
          v-model="form.nodeSizes.controlPlaneIsWorker"
          type="checkbox"
          :required="workerCount === 0"
          :disabled="submitting"
        >
        <span>Control Planes auch als Worker nutzen</span>
      </label>
      <p
        v-if="workerCount === 0 && !form.nodeSizes.controlPlaneIsWorker"
        class="notice notice--warning"
        role="alert"
      >
        Ohne separate Worker müssen die Control Planes auch als Worker genutzt werden.
      </p>
    </section>

    <section class="panel">
      <h2>Storage</h2>
      <p class="node-help">
        Optional: Block-Storage, der über beide Berliner Standorte gespiegelt ist und im Cluster
        als StorageClass <code>ceph-rbd-stretch</code> bereitsteht. Die Größe ist der Speicherplatz,
        den der Cluster insgesamt belegen darf.
      </p>
      <label class="checkbox-row">
        <input
          v-model="form.cephStorageEnabled"
          type="checkbox"
          :disabled="submitting"
        >
        <span>Gestreckter Ceph-Block-Storage</span>
      </label>
      <div v-if="form.cephStorageEnabled" class="form-grid storage-grid">
        <label>
          Größe in GB ({{ storageLimits.min }}–{{ storageLimits.max }}, {{ storageLimits.step }}er-Schritte)
          <input
            :class="{ 'input-error': storageError }"
            v-model.number="form.cephStorageGiB"
            type="number"
            :min="storageLimits.min"
            :max="storageLimits.max"
            :step="storageLimits.step"
            :disabled="submitting"
          >
          <small v-if="storageError" class="field-error" role="alert">
            {{ storageError }}
          </small>
        </label>
        <label>
          Verschlüsselung
          <select
            v-model="form.cephStorageEncryptionMode"
            :disabled="submitting"
          >
            <option
              v-for="mode in encryptionModes"
              :key="mode.value"
              :value="mode.value"
            >
              {{ mode.label }}
            </option>
          </select>
          <small class="node-help">
            Für die Lebensdauer des Speichers unveränderlich. Beim kundeneigenen Schlüssel liegt der
            Schlüssel im Schlüsseldienst des Kunden; die Plattform kann die Volumes nicht lesen.
          </small>
        </label>
      </div>
    </section>

    <section class="panel">
      <h2>Backup</h2>
      <p class="node-help">
        Optional: Die Plattform richtet nach dem Clusterbau das S3-Ziel und die Zugangsdaten ein
        und rollt Velero mit den Standard-Sicherungsplänen auf den Cluster aus. Ohne Auswahl wird
        kein Velero installiert.
      </p>
      <label class="checkbox-row">
        <input
          v-model="form.veleroBackup"
          type="checkbox"
          :disabled="submitting"
        >
        <span>Velero-Backup einrichten</span>
      </label>
    </section>

    <section v-if="selectedCustomer" class="panel">
      <h2>Routing-Zonen</h2>
      <p v-if="!customerZones.length">
        Für diesen Kunden gibt es noch keine aktive Routing-Zone — die Bestellung legt eine neue an.
      </p>
      <div v-else class="site-grid">
        <article v-for="zone in customerZones" :key="zone.fabricVrfId">
          <strong v-if="zone.label">{{ zone.label }}</strong>
          <strong>{{ zone.name }}</strong>
          <span>VLAN {{ zone.rzVlan }} · MSP {{ zone.mspId }}</span>
          <span>{{ zoneClusters(zone) }}</span>
        </article>
      </div>
      <div class="form-grid">
        <label>
          Netzwerkmodus
          <select v-model="form.networkMode" :disabled="submitting">
            <option value="new">Neue Routing-Zone anlegen</option>
            <option value="existing" :disabled="!customerZones.length">
              In bestehende Routing-Zone deployen
            </option>
          </select>
        </label>
        <label v-if="form.networkMode === 'new'">
          Bezeichnung der neuen Zone (optional)
          <input
            v-model.trim="form.zoneLabel"
            type="text"
            maxlength="24"
            placeholder="z. B. sfh-prod oder dev"
            :disabled="submitting"
          >
          <small>1–24 Zeichen: Kleinbuchstaben, Ziffern, Bindestrich. Erscheint im Katalog, als Cluster-Label und als Apstra-Tag; der technische Zonenname bleibt.</small>
        </label>
        <label v-if="form.networkMode === 'existing'">
          Ziel-Routing-Zone
          <select v-model="form.fabricVrfId" :disabled="submitting">
            <option value="">– Routing-Zone wählen –</option>
            <option
              v-for="zone in customerZones"
              :key="zone.fabricVrfId"
              :value="zone.fabricVrfId"
            >
              {{ zoneDisplay(zone) }}
            </option>
          </select>
        </label>
      </div>
      <p v-if="form.networkMode === 'existing'" class="notice">
        Der neue Cluster teilt sich Routing-Domäne und Adressraum mit den bestehenden
        Clustern dieser Zone (z.&nbsp;B. gemeinsame Dev- oder Prod-Zone). VIP und Dienste
        bleiben clustereigen; die Zuordnung wird serverseitig gegen Eigentum und
        Slot-Identität geprüft.
      </p>
    </section>

    <section class="panel">
      <h2>Feste Standorte</h2>
      <div class="site-grid">
        <article>
          <strong>Berlin 1</strong>
          <span>Harvester · {{ form.nodeSizes.controlPlane.countBerlin1 }} Control Plane · {{ form.nodeSizes.worker.countBerlin1 }} Worker</span>
          <span class="site-resources">{{ resourceTotals.berlin1.nodes }} Nodes · {{ resourceTotals.berlin1.cpu }} vCPU · {{ resourceTotals.berlin1.memory }} GiB RAM · {{ resourceTotals.berlin1.disk }} GiB Disk</span>
        </article>
        <article>
